select tm.id, tm.member_id, tm.member_name, tm.template_id, tm.create_time, tm.update_time, tm.create_user_id, tm.create_user_name, tm.update_user_id, tm.update_user_name from template_members tm inner join template_role_ref_members trrm on trrm.members_id = tm.id and trrm.template_id = tm.template_id
trrm.role_id = #{roleId} and trrm.template_id = #{templateId}
ORDER BY tm.create_time DESC
